from math import isqrt


def _is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    limit = isqrt(n)
    divisor = 3
    while divisor <= limit:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def solve(value):
    classified = {}
    result = []
    for number in value:
        if number not in classified:
            classified[number] = _is_prime(number)
        result.append(classified[number])
    return result
